using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
static class RoofingPaySpecification {
 public const string Metal="Pre-painted metal",Upvc="uPVC";
 public static string LegacyMaterial(string name){return (name??"").IndexOf("upvc",StringComparison.OrdinalIgnoreCase)>=0?Upvc:Metal;}
 public static void ValidateMaterial(string material){if(material!=Metal&&material!=Upvc)throw new Exception("Choose Pre-painted metal or uPVC for the saved roof profile.");}
 public static double Thickness(string material,double upvc){ValidateMaterial(material);if(upvc!=2&&upvc!=2.5&&upvc!=3)throw new Exception("Choose uPVC thickness 2.0, 2.5 or 3.0mm.");return material==Metal?.6:upvc;}
 public static BackupTarget Target(string material,string family,double upvc){double thickness=Thickness(material,upvc);bool rib=family=="Longspan Rib";if(!rib&&family!="Longspan Corrugated")throw new Exception("Unknown roofing family.");string type=rib?"Rib":"Corrugated";return new BackupTarget{Code=material==Upvc?"1013(5)":rib?"1014(1)b2":"1014(1)a2",Description=thickness.ToString("0.00",CultureInfo.InvariantCulture)+"mm thk. "+type+" Type "+(material==Upvc?"uPVC Thermoplastic Roofing Sheet":"Pre-painted Metal Sheet")+" (Long Span)",Unit="sq.m."};}
}
partial class ProgramOfWorksForm {
 ComboBox upvcThickness;
 void AddRoofingProjectSpecification(){roofProfiles.Columns.Add(new DataGridViewComboBoxColumn{Name="Material",HeaderText="Material",Width=180,ReadOnly=false});var material=(DataGridViewComboBoxColumn)roofProfiles.Columns[6];material.Items.AddRange(RoofingPaySpecification.Metal,RoofingPaySpecification.Upvc);material.DisplayIndex=1;var start=tabs.TabPages.Cast<TabPage>().Single(p=>p.Text=="Roofing Start");var tools=start.Controls.OfType<FlowLayoutPanel>().First();tools.Controls.Add(new Label{Text="Pre-painted metal: 0.60 mm (fixed)",AutoSize=true,Padding=new Padding(8)});upvcThickness=SettingChoice(tools,"Project uPVC thickness mm",new[]{"3.0","2.5","2.0"});upvcThickness.SelectedIndexChanged+=(s,e)=>{if(!filling&&!initializingWorks)Recalculate();};}
 double ProjectUpvcThickness{get{return upvcThickness==null?3:double.Parse(upvcThickness.Text,CultureInfo.InvariantCulture);}}
 void AddRoofProfileRow(RoofProfile profile){roofProfiles.Rows.Add(profile.Name,profile.Family,(profile.Width*1000).ToString("R",CultureInfo.InvariantCulture),profile.SideLap,(profile.Cover*1000).ToString("R",CultureInfo.InvariantCulture),"",profile.MaterialType);}
 List<BillQuantity> RoofSheetPayQuantities(){var result=new List<BillQuantity>();foreach(DataGridViewRow row in roofSheets.Rows){var quantity=row.Tag as RoofSheetQuantity;if(quantity==null)continue;var profile=savedRoofProfiles.FirstOrDefault(p=>string.Equals(p.Name,Cell(row,2),StringComparison.OrdinalIgnoreCase)&&p.SideLap==Cell(row,17));if(profile==null)continue;var target=RoofingPaySpecification.Target(profile.MaterialType,profile.Family,ProjectUpvcThickness);var item=result.FirstOrDefault(q=>q.PayCode==target.Code&&q.Description==target.Description);if(item==null){item=new BillQuantity{Section="Roofing Works",Description=target.Description,PayCode=target.Code,PayDescription=target.Description,Unit="m2"};result.Add(item);}item.Quantity+=quantity.BuyArea;item.Sources.Add(new BillQuantity{Description=Cell(row,0)+" | "+Cell(row,1)+" | "+profile.Name+" | "+Cell(row,17),Quantity=quantity.BuyArea,Unit="m2",Computation="Purchased full sheet area; "+profile.MaterialType+", "+RoofingPaySpecification.Thickness(profile.MaterialType,ProjectUpvcThickness).ToString("0.00",CultureInfo.InvariantCulture)+"mm, "+profile.Family});}return result;}
 void WriteRoofingSpecification(XmlElement root){var node=root.OwnerDocument.CreateElement("RoofingSpecifications");root.AppendChild(node);node.SetAttribute("version","1");node.SetAttribute("upvcThicknessMm",ProjectUpvcThickness.ToString("0.0",CultureInfo.InvariantCulture));int index=0;foreach(DataGridViewRow row in roofProfiles.Rows){if(row.IsNewRow||Empty(row))continue;var p=root.OwnerDocument.CreateElement("Profile");node.AppendChild(p);p.SetAttribute("row",(index++).ToString(CultureInfo.InvariantCulture));p.SetAttribute("material",Cell(row,6)==""?RoofingPaySpecification.LegacyMaterial(Cell(row,0)):Cell(row,6));}}
 void ValidateRoofingSpecification(XmlElement root,bool required){var node=root["RoofingSpecifications"];if(node==null){if(required)throw new Exception("Project is missing roofing material specifications.");return;}if(node.GetAttribute("version")!="1")throw new Exception("Unsupported roofing specification format.");RoofingPaySpecification.Thickness(RoofingPaySpecification.Upvc,double.Parse(node.GetAttribute("upvcThicknessMm"),CultureInfo.InvariantCulture));int count=root["RoofProfiles"]==null?0:root["RoofProfiles"].SelectNodes("Entry").Count;var seen=new HashSet<int>();foreach(XmlElement p in node.SelectNodes("Profile")){int n=int.Parse(p.GetAttribute("row"),CultureInfo.InvariantCulture);if(n<0||n>=count||!seen.Add(n))throw new Exception("Invalid roof material row reference.");RoofingPaySpecification.ValidateMaterial(p.GetAttribute("material"));}if(required&&seen.Count!=count)throw new Exception("Incomplete roofing material specifications.");}
 void ReadRoofingSpecification(XmlElement root){ValidateRoofingSpecification(root,false);bool before=filling;filling=true;try{foreach(DataGridViewRow row in roofProfiles.Rows)if(!row.IsNewRow)row.Cells[6].Value=RoofingPaySpecification.LegacyMaterial(Cell(row,0));var node=root["RoofingSpecifications"];upvcThickness.SelectedItem=node==null?"3.0":double.Parse(node.GetAttribute("upvcThicknessMm"),CultureInfo.InvariantCulture).ToString("0.0",CultureInfo.InvariantCulture);if(node!=null)foreach(XmlElement p in node.SelectNodes("Profile"))roofProfiles.Rows[int.Parse(p.GetAttribute("row"),CultureInfo.InvariantCulture)].Cells[6].Value=p.GetAttribute("material");}finally{filling=before;}}
}
}
